func (s *Service) validateDataColumn(ctx context.Context, pid peer.ID, msg *pubsub.Message) (pubsub.ValidationResult, error) {
    // Decode and type-assert to *eth.DataColumnSidecar
    // [REJECT] verifier.ValidFields() calls peerdas.VerifyDataColumnSidecar for each column
